public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    long daysInMonth = 31;
    long daysInYear = 365;
    long timeBucketDays = timeBucket / daysInMonth;
    long timeBucketMonths = timeBucketDays / daysInYear;

    if (dayStep < 12) {
        // Day step is within the same month
        return timeBucket;
    } else if (dayStep < 12 * daysInMonth) {
        // Day step is within the same year
        int monthStep = dayStep / 12;
        int monthOffset = monthStep - (monthStep / 12) * 12;
        return timeBucket - (timeBucketDays % daysInMonth) + (monthOffset * daysInMonth);
    } else {
        // Day step is greater than one year
        int yearStep = dayStep / (daysInYear * 12);
        int yearOffset = yearStep - (yearStep / daysInYear) * daysInYear;
        return timeBucket - (timeBucketDays % daysInYear) + (yearOffset * daysInYear);
    }
}
