/**
 * Loads thread snapshots within a specified time range from a file.
 *
 * Parses the provided file and returns a list of thread snapshots that fall within
 * one of the specified time ranges. If no time ranges are provided, all thread
 * snapshots in the file are returned.
 *
 * @param file the file to read from
 * @param timeRanges the optional time ranges to filter the thread snapshots by
 * @return a list of thread snapshots that fall within the specified time ranges
 * @throws IOException if an I/O error occurs while reading from the file
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(
    File file,
    List<ProfileAnalyzeTimeRange> timeRanges
) throws IOException {
    // Parse file into a list of thread snapshots
    List<ThreadSnapshot> threadSnapshots = parseFromFile(file);

    // Filter thread snapshots by time range, if specified
    if (timeRanges != null && !timeRanges.isEmpty()) {
        long startTime = timeRanges.get(0).getStartTime();
        long endTime = timeRanges.get(0).getEndTime();
        threadSnapshots = threadSnapshots.stream()
            .filter(threadSnapshot -> threadSnapshot.getTimestamp() >= startTime && threadSnapshot.getTimestamp() <= endTime)
            .collect(Collectors.toList());
    }

    return threadSnapshots;
}

